#!/usr/bin/env bash
# Compile-checks the Windows (WinForms) app on Linux.
#
# The RDP ActiveX wrapper (the MSTSCLib COM reference) can only be generated by Windows MSBuild,
# so this check drops that reference and compiles empty stand-ins for the MSTSCLib types instead
# (MstscLibStubs.cs). That lets csc get past the declaration phase and compile every method body;
# the only errors tolerated are the ones about those MSTSCLib types inside the RDP protocol files.
# Any other error fails the check. Windows CI still does the real build.
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
log="$(mktemp)"
trap 'rm -f "$log"' EXIT

dotnet build "$repo_root/mRemoteNG/mRemoteNG.csproj" -c Release -p:Platform=x64 \
    -p:EnableWindowsTargeting=true \
    -p:CustomAfterMicrosoftCommonTargets="$repo_root/scripts/linux/no-com-reference.targets" \
    -nologo -v:q >"$log" 2>&1 || true

errors="$(grep -E ': error ' "$log" | sed -E 's/ \[[^]]*\]$//' | sort -u || true)"
expected='/Connection/Protocol/RDP/[^:]+: error CS[0-9]+: .*(AxMSTSCLib|MSTSCLib|AxMsRdpClient[0-9]+NotSafeForScripting|MsRdpClient[0-9]+NotSafeForScripting|IMsRdp[A-Za-z0-9]*)'
unexpected="$(grep -vE "$expected" <<<"$errors" | grep . || true)"

if [[ -n "$unexpected" ]]; then
    echo "Unexpected build errors in the WinForms app:"
    echo "$unexpected"
    exit 1
fi

echo "WinForms app compiles on Linux, apart from $(grep -c . <<<"$errors" || true) expected MSTSCLib errors."
